<script setup>
import { ref, onBeforeUnmount } from 'vue'
const token=ref(''),rows=ref([]),error=ref(''),busy=ref(false),photos=ref({}),notes=ref({})
let generation=0
function clearPhotos(){for(const urls of Object.values(photos.value))for(const url of urls)URL.revokeObjectURL(url);photos.value={}}
async function load(){busy.value=true;error.value='';const current=++generation;clearPhotos();rows.value=[]
 try{const res=await fetch('/api/poi-submissions',{headers:{Authorization:`Bearer ${token.value}`}});if(!res.ok)throw Error('无法读取，请核对团队审核密钥');const data=await res.json();if(current!==generation)return;rows.value=data;for(const r of data)notes.value[r.id]=r.reviewNote||''}
 catch(e){error.value=e.message}finally{busy.value=false}}
async function showPhotos(row){error.value='';const current=generation;const urls=[]
 try{for(let i=0;i<row.photoCount;i++){const res=await fetch(`/api/poi-submissions/${row.id}/photos/${i}`,{headers:{Authorization:`Bearer ${token.value}`}});if(!res.ok)throw Error('照片读取失败');urls.push(URL.createObjectURL(await res.blob()))}if(current!==generation){urls.forEach(URL.revokeObjectURL);return}photos.value[row.id]=urls}catch(e){urls.forEach(URL.revokeObjectURL);error.value=e.message}}
async function update(row,status){busy.value=true;error.value='';try{const res=await fetch(`/api/poi-submissions/${row.id}`,{method:'PATCH',headers:{Authorization:`Bearer ${token.value}`,'Content-Type':'application/json'},body:JSON.stringify({status,reviewNote:notes.value[row.id]||''})});if(!res.ok)throw Error('保存失败');Object.assign(row,await res.json())}catch(e){error.value=e.message}finally{busy.value=false}}
function logout(){generation++;clearPhotos();token.value='';rows.value=[];error.value=''}
onBeforeUnmount(()=>{generation++;clearPhotos()})
</script>
<template><main class="page review"><router-link to="/">← 首页</router-link><h1>点位投稿审核</h1><p class="hint">核对位置、照片及作品关联后标记为「待收录」，整理进入正式点位库后再发布。</p><form class="auth" @submit.prevent="load"><label for="review-token">团队审核密钥</label><input id="review-token" v-model="token" type="password" autocomplete="off" placeholder="仅本次页面会话使用" required/><button class="btn" :disabled="busy">读取投稿</button><button type="button" class="btn-ghost" @click="logout">退出</button></form><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="busy" role="status">处理中…</p><p v-if="rows.length" class="hint">共 {{rows.length}} 条投稿；照片按需读取。</p><article v-for="row in rows" :key="row.id"><header><h2>{{row.place.name}}</h2><span>{{row.status}}</span></header><p class="hint">{{row.lineId}} · {{row.type==='ip'?'IP 点':'其他点'}} · {{new Date(row.createdAt).toLocaleString('zh-CN')}}</p><p>{{row.place.address}} · {{row.place.lat}}, {{row.place.lng}}</p><p v-if="row.locationDetail">具体位置：{{row.locationDetail}}</p><p>{{row.intro}}</p><p v-if="row.tips">实用补充：{{row.tips}}</p><section v-if="row.type==='ip'"><h3>作品关联</h3><p>{{row.edition}} · {{row.relation}} · {{row.alias}}</p><p>{{row.scene}}</p><p>章节/集数：{{row.chapter || '待查证'}}</p><blockquote>{{row.excerpt || '未提供节选，由团队查证'}}</blockquote><p>来源：{{row.source || '待查证'}}</p></section><button v-if="!photos[row.id]" class="btn-ghost" @click="showPhotos(row)">查看 {{row.photoCount}} 张照片</button><div class="photos"><img v-for="url in photos[row.id]||[]" :key="url" :src="url" alt="投稿景点照"/></div><label :for="`note-${row.id}`">审核备注</label><textarea :id="`note-${row.id}`" v-model="notes[row.id]" maxlength="1000" placeholder="位置/主体人物/使用授权/IP 关联/待补资料"/><div class="actions"><button v-for="s in ['待审核','待收录','需补充','不收录']" :key="s" class="btn-ghost" :disabled="busy" @click="update(row,s)">{{s}}</button></div><small>{{row.id}}</small></article></main></template>
<style scoped>.review{max-width:960px}h1{font-family:serif;margin:24px 0 10px}.hint{font-size:12px;color:var(--ink-2);margin:10px 0}.auth{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:24px 0}.auth input{flex:1;min-width:180px}input,textarea{padding:12px;border:1px solid var(--line);border-radius:10px;font:inherit;background:white}article{background:#fff;border:1px solid var(--line);border-radius:18px;padding:24px;margin:20px 0}header{display:flex;justify-content:space-between;gap:12px}header h2{font-family:serif;font-size:22px}header span{color:var(--brand);font-size:13px}article p{margin:12px 0;font-size:14px;white-space:pre-wrap;overflow-wrap:anywhere}section{padding:16px;background:var(--bg);border-radius:12px;margin:18px 0}section h3{font-size:14px}blockquote{white-space:pre-wrap;font-size:14px}.photos{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.photos img{width:200px;max-width:100%;height:150px;object-fit:contain;background:var(--bg)}textarea{width:100%;margin:8px 0}.actions{display:flex;gap:8px;flex-wrap:wrap}small{display:block;font-size:11px;color:var(--ink-2);margin-top:16px}.error{color:var(--brand)}</style>
